package tacc

import org.antlr.v4.runtime.BaseErrorListener
import org.antlr.v4.runtime.CharStreams
import org.antlr.v4.runtime.CommonTokenStream
import org.antlr.v4.runtime.Parser
import org.antlr.v4.runtime.RecognitionException
import org.antlr.v4.runtime.Recognizer
import org.antlr.v4.runtime.Token
import org.antlr.v4.runtime.misc.IntervalSet

/**
 * Front end: source text -> tokens -> parse tree -> AST.
 *
 * Lexing and parsing are generated by ANTLR 4 from `src/main/antlr/tacc/Tc.g4`. This file turns
 * ANTLR's error reporting into [LexError] / [ParseError] with the source line, stopping at the
 * first error, and [AstBuilder] converts the parse tree into the AST in `Ast.kt`.
 */

/** Base class for every error reported as `<file>:<line>: error: <message>`. */
open class CompileError(message: String, val line: Int) : Exception(message)

class LexError(message: String, line: Int) : CompileError(message, line)

class ParseError(message: String, line: Int) : CompileError(message, line)

/** Parses [source] into an AST. Throws [LexError] or [ParseError] on the first error. */
fun parseProgram(source: String): Program {
    val parser = TcParser(tokenize(source))
    parser.removeErrorListeners()
    parser.addErrorListener(ParseErrorListener)
    return AstBuilder().program(parser.program())
}

/**
 * Runs the lexer over the whole source and checks every token, so that all lexical errors are
 * reported before any syntax error.
 */
fun tokenize(source: String): CommonTokenStream {
    val lexer = TcLexer(CharStreams.fromString(source))
    lexer.removeErrorListeners()
    lexer.addErrorListener(LexErrorListener)
    val tokens = CommonTokenStream(lexer)
    tokens.fill()
    for (token in tokens.tokens) {
        when (token.type) {
            TcLexer.ERROR_CHAR -> throw LexError("unexpected character '${token.text}'", token.line)
            TcLexer.UNTERMINATED_STRING -> throw LexError("unterminated string literal", token.line)
            TcLexer.BAD_INT -> throw LexError("invalid integer literal '${token.text}'", token.line)
            TcLexer.STRING -> stringValue(token)
            TcLexer.INT -> intValue(token)
        }
    }
    return tokens
}

/** Value of a STRING token: quotes removed, escapes `\"`, `\\`, `\n` resolved (spec/language.md). */
fun stringValue(token: Token): String {
    val text = token.text
    val sb = StringBuilder()
    var i = 1
    while (i < text.length - 1) {
        val c = text[i]
        if (c == '\\') {
            when (val e = text[i + 1]) {
                '"' -> sb.append('"')
                '\\' -> sb.append('\\')
                'n' -> sb.append('\n')
                else -> throw LexError("invalid escape sequence '\\$e'", token.line)
            }
            i += 2
        } else {
            sb.append(c)
            i++
        }
    }
    return sb.toString()
}

/** Value of an INT token; it must fit in a signed 64-bit integer (spec/language.md). */
fun intValue(token: Token): Long =
    token.text.toLongOrNull()
        ?: throw LexError("integer literal ${token.text} does not fit in a signed 64-bit integer", token.line)

private object LexErrorListener : BaseErrorListener() {
    // Not expected: ERROR_CHAR matches any character the other rules do not.
    override fun syntaxError(
        recognizer: Recognizer<*, *>?,
        offendingSymbol: Any?,
        line: Int,
        charPositionInLine: Int,
        msg: String?,
        e: RecognitionException?,
    ) {
        throw LexError(msg ?: "lexical error", line)
    }
}

/**
 * Reports the first syntax error as `expected <what>, found <token>` instead of ANTLR's default
 * messages, and stops parsing by throwing.
 */
private object ParseErrorListener : BaseErrorListener() {
    override fun syntaxError(
        recognizer: Recognizer<*, *>?,
        offendingSymbol: Any?,
        line: Int,
        charPositionInLine: Int,
        msg: String?,
        e: RecognitionException?,
    ) {
        val parser = recognizer as Parser
        val expected = e?.expectedTokens ?: parser.expectedTokens
        val found = describe(offendingSymbol as Token)
        val what = describeExpected(expected, parser)
        throw ParseError(if (what == null) "unexpected $found" else "expected $what, found $found", line)
    }

    private fun describe(token: Token): String =
        if (token.type == Token.EOF) "end of file" else "'${token.text}'"

    private fun describeExpected(expected: IntervalSet, parser: Parser): String? {
        // Grammar order, with "end of file" last.
        val types = expected.toList().sortedBy { if (it == Token.EOF) Int.MAX_VALUE else it }
        return when {
            // Only the start of a statement allows `let`; only the start of an expression allows an integer.
            TcParser.LET in types -> if (TcParser.RBRACE in types) "a statement or '}'" else "a statement"
            TcParser.INT in types -> "an expression"
            types == listOf(TcParser.INT_TYPE, TcParser.BOOL_TYPE, TcParser.STRING_TYPE) -> "type 'Int', 'Bool' or 'String'"
            types.isEmpty() || types.size > 4 -> null
            else -> {
                val names = types.map { name(it, parser) }
                if (names.size == 1) names[0] else names.dropLast(1).joinToString(", ") + " or " + names.last()
            }
        }
    }

    private fun name(type: Int, parser: Parser): String = when (type) {
        Token.EOF -> "end of file"
        TcParser.IDENT -> "a name"
        TcParser.STRING -> "a string literal"
        else -> parser.vocabulary.getDisplayName(type)
    }
}
